const item = $input.first().json;
const body = item.body || {};
const headers = item.headers || {};

const receivedSignature = headers['x-kredo-signature'] || headers['X-KREDO-Signature'] || '';
const expectedSignature = 'sha256=' + (item.computedSignature || '');

if (!receivedSignature || receivedSignature !== expectedSignature) {
  throw new Error('Signature HMAC invalide (X-KREDO-Signature) — requête rejetée');
}

const required = ['runId', 'workspaceId', 'companyId', 'userId', 'settings', 'callbackUrl'];
for (const field of required) {
  if (!body[field]) throw new Error(`Champ requis manquant dans le payload : ${field}`);
}

const settings = body.settings || {};

return [{
  json: {
    runId: body.runId,
    workspaceId: body.workspaceId,
    companyId: body.companyId,
    userId: body.userId,
    triggerMode: body.triggerMode || 'manual',
    watchLevel: body.watchLevel || settings.watchLevel || 'standard',
    settings: {
      isEnabled: settings.isEnabled !== false,
      watchLevel: settings.watchLevel || 'standard',
      cadence: settings.cadence || 'weekly',
      includeOfficialSite: settings.includeOfficialSite !== false,
      includeNews: settings.includeNews !== false,
      includeJobs: settings.includeJobs !== false,
      includePublicRecords: settings.includePublicRecords === true,
      includeTenders: settings.includeTenders === true,
      includeSocialManual: settings.includeSocialManual === true,
      queryAliases: Array.isArray(settings.queryAliases) ? settings.queryAliases.filter((v) => typeof v === 'string') : [],
    },
    callbackUrl: body.callbackUrl,
  }
}];

const ctx = $('Validate Payload').item.json;
const companyRaw = $('Load Company Details').item?.json;
const company = (companyRaw && companyRaw.id) ? companyRaw : { id: ctx.companyId, name: null, website: null, sector: null, description: null };

const existingDedupeKeys = $input.all().map((i) => i.json && i.json.dedupe_key).filter(Boolean);

const aliases = (ctx.settings.queryAliases || []).filter(Boolean);
const nameVariants = [company.name, ...aliases].filter(Boolean);
const primaryName = company.name || aliases[0] || 'entreprise inconnue';

return [{
  json: {
    runId: ctx.runId,
    workspaceId: ctx.workspaceId,
    companyId: ctx.companyId,
    userId: ctx.userId,
    watchLevel: ctx.watchLevel,
    settings: ctx.settings,
    callbackUrl: ctx.callbackUrl,
    company: {
      id: company.id || ctx.companyId,
      name: company.name || null,
      website: company.website || null,
      sector: company.sector || null,
      description: company.description || null,
    },
    primaryName,
    nameVariants,
    existingDedupeKeys,
    collectedItems: [],
  }
}];

// Extraction best-effort : le site officiel n'a pas d'API standard, on scanne
// le HTML de la homepage pour repérer des liens de type "actualités/presse".
// Source la moins fiable des 5 collecteurs — reliability_score plus bas (0.75).
const ctx = $('Build Targeted Queries').first().json;
const raw = $input.all();
const errorItem = raw.find((i) => i.json && i.json.error);

let newItems = [];
if (!errorItem && ctx.settings.includeOfficialSite && ctx.company.website) {
  const html = (raw[0] && (raw[0].json.data || raw[0].json.body || raw[0].json.html)) || '';
  const anchorRegex = /<a\s[^>]*href=["']([^"']+)["'][^>]*>([^<]{4,120})<\/a>/gi;
  const keywords = /actualit|presse|news|communiqu|blog/i;
  const seen = new Set();
  let match;
  while ((match = anchorRegex.exec(html)) && newItems.length < 8) {
    const href = match[1];
    const text = match[2].replace(/\s+/g, ' ').trim();
    if (!keywords.test(href) && !keywords.test(text)) continue;
    if (seen.has(href)) continue;
    seen.add(href);
    let absoluteUrl = href;
    try { absoluteUrl = new URL(href, ctx.company.website).toString(); } catch (e) { continue; }
    newItems.push({
      title: text || 'Actualité — site officiel',
      url: absoluteUrl,
      publishedAt: null,
      snippet: text,
      sourceType: 'official_site',
      sourceName: ctx.company.name || 'Site officiel',
      collectionMethod: 'scrape',
    });
  }
}

return [{
  json: {
    ...ctx,
    collectedItems: [...ctx.collectedItems, ...newItems],
  }
}];

const ctx = $('Shape+Accumulate: Official Site').first().json;
const raw = $input.all();
const errorItem = raw.find((i) => i.json && i.json.error);

let newItems = [];
if (!errorItem && ctx.settings.includeNews) {
  newItems = raw.filter((i) => i.json && i.json.title).map((i) => ({
    title: i.json.title,
    url: i.json.link,
    publishedAt: i.json.isoDate || i.json.pubDate || null,
    snippet: (i.json.contentSnippet || i.json.content || '').slice(0, 600),
    sourceType: 'news_media',
    sourceName: 'Google News',
    collectionMethod: 'scrape',
  }));
}

return [{
  json: {
    ...ctx,
    collectedItems: [...ctx.collectedItems, ...newItems],
  }
}];

