const ctx = $input.first().json;
const items = Array.isArray(ctx.collectedItems) ? ctx.collectedItems : [];
const existingKeys = new Set(ctx.existingDedupeKeys || []);

function simpleHash(str) {
  let hash = 0;
  for (let i = 0; i < str.length; i++) {
    hash = ((hash << 5) - hash) + str.charCodeAt(i);
    hash |= 0;
  }
  return Math.abs(hash).toString(36);
}

const seenInBatch = new Set();
const deduped = [];
for (const it of items) {
  if (!it.url || !it.title) continue;
  const dedupeKey = `${it.sourceType}:${simpleHash(it.url)}`;
  if (existingKeys.has(dedupeKey)) continue;
  if (seenInBatch.has(dedupeKey)) continue;
  seenInBatch.add(dedupeKey);
  deduped.push({ ...it, dedupeKey, id: `item_${deduped.length}` });
}

// Garde-fou coût LLM : même plafond que la veille hebdomadaire (40 candidats max).
const capped = deduped.slice(0, 40);

return [{
  json: {
    runId: ctx.runId,
    workspaceId: ctx.workspaceId,
    companyId: ctx.companyId,
    callbackUrl: ctx.callbackUrl,
    company: ctx.company,
    normalizedItems: capped,
    itemsCollectedTotal: items.length,
    itemsAfterDedup: capped.length,
  }
}];

const upstream = $('Build Qualification Prompt').first().json;
const response = $input.first().json;

// Detection explicite d'une réponse tronquée par max_tokens : sinon l'échec ne
// se voit qu'indirectement via un JSON.parse cassé plus bas, avec un message
// confus (un simple extrait de texte). Ici l'erreur nomme la vraie cause.
if (response.stop_reason === 'max_tokens') {
  throw new Error(`Qualification LLM tronquée (stop_reason=max_tokens, ${(response.usage && response.usage.output_tokens) || '?'} tokens de sortie) — augmenter max_tokens sur le nœud "LLM Batch Qualification" ou réduire le plafond d'items par lot (actuellement 40, cf. Normalize & Dedup Items).`);
}

const textBlock = (response.content || []).find((b) => b.type === 'text');
const rawText = (textBlock && textBlock.text) || '';

function extractJson(text) {
  const fenced = text.match(/^```(?:json)?\s*([\s\S]*?)\s*```$/i);
  if (fenced) return fenced[1].trim();
  const first = text.indexOf('{');
  const last = text.lastIndexOf('}');
  if (first >= 0 && last > first) return text.slice(first, last + 1);
  return text;
}

function repair(text) {
  return text.replace(/[\u201c\u201d]/g, '"').replace(/[\u2018\u2019]/g, "'").replace(/,\s*([}\]])/g, '$1');
}

let parsed;
try {
  parsed = JSON.parse(repair(extractJson(rawText)));
} catch (e) {
  throw new Error('Qualification LLM : réponse non-JSON exploitable : ' + rawText.slice(0, 300));
}

const byId = new Map((upstream.normalizedItems || []).map((it) => [it.id, it]));
const TAXONOMY = new Set(['leadership_change','growth_event','it_transformation','cyber_risk','regulatory_window','public_tender','hiring_signal','market_pressure','partnership_or_vendor','weak_signal']);

const qualifiedItems = (parsed.items || []).map((q) => {
  const base = byId.get(q.id);
  if (!base) return null;
  const category = TAXONOMY.has(q.category) ? q.category : 'weak_signal';
  const clamp01 = (v) => Math.max(0, Math.min(1, typeof v === 'number' ? v : 0));
  return {
    ...base,
    category,
    pertinenceEsn: clamp01(q.pertinence_esn),
    urgence: clamp01(q.urgence),
    fitPractice: clamp01(q.fit_practice),
    confidence: clamp01(q.confidence),
    summary: q.summary || base.title,
    justification: q.justification || '',
    recommendedAction: q.recommended_action || null,
  };
}).filter(Boolean);

return [{
  json: {
    runId: upstream.runId,
    workspaceId: upstream.workspaceId,
    companyId: upstream.companyId,
    callbackUrl: upstream.callbackUrl,
    company: upstream.company,
    itemsCollectedTotal: upstream.itemsCollectedTotal,
    itemsAfterDedup: upstream.itemsAfterDedup,
    qualifiedItems,
    llmModel: response.model || 'claude-sonnet-5',
    llmTokensInput: (response.usage && response.usage.input_tokens) || null,
    llmTokensOutput: (response.usage && response.usage.output_tokens) || null,
  }
}];

const data = $input.first().json;

const RELIABILITY_BY_SOURCE_TYPE = {
  official_site: 0.75,
  news_media: 0.55,
  job_board: 0.6,
  regulatory_filing: 0.7,
  public_tender: 0.65,
};

function freshness(publishedAt) {
  if (!publishedAt) return 0.5;
  const d = new Date(publishedAt);
  if (isNaN(d)) return 0.5;
  const ageHours = (Date.now() - d.getTime()) / 3600000;
  if (ageHours <= 48) return 1.0;
  const ageDays = ageHours / 24;
  if (ageDays >= 30) return 0.0;
  return Math.max(0, Math.min(1, 1 - (ageDays - 2) / 28));
}

let scored = data.qualifiedItems.map((it) => {
  const reliability = RELIABILITY_BY_SOURCE_TYPE[it.sourceType] ?? 0.5;
  const fresh = freshness(it.publishedAt);
  const globalScore = Math.round((0.35 * it.pertinenceEsn + 0.20 * fresh + 0.20 * it.urgence + 0.15 * it.fitPractice + 0.10 * reliability) * 1000) / 1000;
  const now = new Date();
  const detectedAt = now.toISOString();
  const expiresAt = new Date(now.getTime() + 60 * 24 * 3600 * 1000).toISOString();
  const status = it.confidence < 0.40 ? 'needs_review' : 'new';

  return {
    ...it,
    reliability,
    freshness: fresh,
    globalScore,
    detectedAt,
    expiresAt,
    status,
  };
});

// Règle "source trop bruyante" (§10) : si une source dépasse 20 signaux sur ce run,
// ne conserver que les 5 au score global le plus élevé pour cette source.
const bySource = new Map();
for (const it of scored) {
  const key = `${it.sourceType}::${it.sourceName}`;
  if (!bySource.has(key)) bySource.set(key, []);
  bySource.get(key).push(it);
}

let capped = [];
for (const group of bySource.values()) {
  if (group.length > 20) {
    group.sort((a, b) => b.globalScore - a.globalScore);
    capped.push(...group.slice(0, 5));
  } else {
    capped.push(...group);
  }
}

return [{
  json: {
    runId: data.runId,
    workspaceId: data.workspaceId,
    companyId: data.companyId,
    callbackUrl: data.callbackUrl,
    company: data.company,
    itemsCollectedTotal: data.itemsCollectedTotal,
    itemsAfterDedup: data.itemsAfterDedup,
    scoredItems: capped,
    noisySourcesCapped: bySource.size !== capped.length ? true : false,
    llmModel: data.llmModel,
    llmTokensInput: data.llmTokensInput,
    llmTokensOutput: data.llmTokensOutput,
  }
}];

const data = $input.first().json;

function canonicalUrl(url) {
  try {
    const u = new URL(url);
    u.search = '';
    u.hash = '';
    return u.toString();
  } catch (e) {
    return url;
  }
}

const bySourceKey = new Map();
for (const it of data.scoredItems) {
  const sourceKey = `account_watch:${it.sourceType}:${it.dedupeKey}`;
  if (bySourceKey.has(sourceKey)) continue;
  bySourceKey.set(sourceKey, {
    workspace_id: data.workspaceId,
    source_type: it.sourceType,
    source_name: it.sourceName,
    source_url: it.url,
    canonical_url: canonicalUrl(it.url),
    published_at: it.publishedAt || null,
    source_key: sourceKey,
    evidence_excerpt: (it.snippet || it.summary || '').slice(0, 500),
    reliability_score: it.reliability,
    collection_method: it.collectionMethod,
    technical_metadata: { collector: 'intel-033-account-watch-refresh', runId: data.runId },
  });
}

const sourcesPayload = Array.from(bySourceKey.values());
const sourceKeys = Array.from(bySourceKey.keys());

return [{
  json: {
    runId: data.runId,
    workspaceId: data.workspaceId,
    companyId: data.companyId,
    callbackUrl: data.callbackUrl,
    company: data.company,
    itemsCollectedTotal: data.itemsCollectedTotal,
    itemsAfterDedup: data.itemsAfterDedup,
    scoredItems: data.scoredItems,
    sourcesPayload,
    sourceKeys,
    noisySourcesCapped: data.noisySourcesCapped,
    llmModel: data.llmModel,
    llmTokensInput: data.llmTokensInput,
    llmTokensOutput: data.llmTokensOutput,
  }
}];

const data = $('Build Sources Payload').first().json;
const resolved = $input.all().map((i) => i.json).filter((r) => r && r.source_key);
const idBySourceKey = new Map(resolved.map((r) => [r.source_key, r.id]));

const dedupeKeyToSourceKey = new Map();
for (const it of data.scoredItems) {
  dedupeKeyToSourceKey.set(it.dedupeKey, `account_watch:${it.sourceType}:${it.dedupeKey}`);
}

const signalsPayload = data.scoredItems.map((it) => {
  const sourceKey = dedupeKeyToSourceKey.get(it.dedupeKey);
  const sourceId = idBySourceKey.get(sourceKey) || null;
  return {
    workspace_id: data.workspaceId,
    company_id: data.companyId,
    signal_category: it.category,
    signal_type: `account_watch_${it.sourceType}`,
    title: it.title.slice(0, 500),
    summary: it.summary,
    event_at: it.publishedAt || null,
    detected_at: it.detectedAt,
    last_evidence_at: it.detectedAt,
    expires_at: it.expiresAt,
    dedupe_key: it.dedupeKey,
    confidence_score: it.confidence,
    relevance_score: it.pertinenceEsn,
    urgency_score: it.urgence,
    potential_value_score: it.fitPractice,
    global_score: it.globalScore,
    score_details: {
      pertinence_esn: it.pertinenceEsn,
      freshness: it.freshness,
      urgence: it.urgence,
      fit_practice: it.fitPractice,
      reliability: it.reliability,
      weights: { pertinence_esn: 0.35, freshness: 0.20, urgence: 0.20, fit_practice: 0.15, reliability: 0.10 },
    },
    score_justification: it.justification,
    recommended_action: it.recommendedAction,
    status: it.status,
    run_id: data.runId,
    primary_source_id: sourceId,
  };
});

return [{
  json: {
    runId: data.runId,
    workspaceId: data.workspaceId,
    companyId: data.companyId,
    callbackUrl: data.callbackUrl,
    company: data.company,
    itemsCollectedTotal: data.itemsCollectedTotal,
    itemsAfterDedup: data.itemsAfterDedup,
    noisySourcesCapped: data.noisySourcesCapped,
    signalsPayload,
    llmModel: data.llmModel,
    llmTokensInput: data.llmTokensInput,
    llmTokensOutput: data.llmTokensOutput,
  }
}];

const insertedSignals = $input.all().map((i) => i.json).filter((r) => r && r.id);

const linksPayload = insertedSignals
  .filter((s) => s.primary_source_id)
  .map((s) => ({
    workspace_id: s.workspace_id,
    source_id: s.primary_source_id,
    object_type: 'signal',
    object_id: s.id,
    link_role: 'supporting',
  }));

return linksPayload.map((l) => ({ json: l }));

const data = $('Map Signals to Sources').first().json;

const byCategory = {};
for (const s of data.signalsPayload) {
  byCategory[s.signal_category] = (byCategory[s.signal_category] || 0) + 1;
}

const contentJson = {
  companyName: data.company.name,
  itemsCollectedTotal: data.itemsCollectedTotal,
  itemsAfterDedup: data.itemsAfterDedup,
  signalsCreated: data.signalsPayload.length,
  signalsByCategory: byCategory,
  noisySourcesCapped: data.noisySourcesCapped,
};

const callbackBody = {
  n8nExecutionId: $execution.id,
  n8nWorkflowId: $workflow.id,
  runId: data.runId,
  phase: 1,
  resultType: 'account_watch_refresh',
  status: 'succeeded',
  contentJson,
  contentText: `Veille compte ${data.company.name || ''} : ${data.signalsPayload.length} signal(aux) sur ${data.itemsAfterDedup} élément(s) retenu(s) (${data.itemsCollectedTotal} collecté(s)).`,
  title: `Veille — ${data.company.name || 'Compte'}`,
  modelProvider: 'anthropic',
  modelUsed: data.llmModel,
  tokensInput: data.llmTokensInput,
  tokensOutput: data.llmTokensOutput,
  contextSnapshot: { itemsAfterDedup: data.itemsAfterDedup, signalsCreated: data.signalsPayload.length },
  sourceRefs: [],
  qaFlags: [],
};

return [{ json: { callbackUrl: data.callbackUrl, rawBody: JSON.stringify(callbackBody) } }];

const errItem = $input.first().json;
let runId = null;
let callbackUrl = null;
let companyId = null;
let workspaceId = null;

try {
  const vp = $('Validate Payload').item.json;
  runId = vp.runId || null;
  callbackUrl = vp.callbackUrl || null;
  companyId = vp.companyId || null;
  workspaceId = vp.workspaceId || null;
} catch (e) {
  // Validate Payload n'a produit aucune sortie exploitable (payload rejeté avant validation).
}

let errorMessage = 'Erreur inconnue dans le workflow intel-033-account-watch-refresh';
if (errItem && errItem.error) {
  errorMessage = typeof errItem.error === 'string' ? errItem.error : (errItem.error.message || JSON.stringify(errItem.error));
} else if (errItem && errItem.message) {
  errorMessage = errItem.message;
}

// Si le payload a été rejeté avant la validation (signature invalide ou champ
// requis manquant, callbackUrl compris), on ne connaît aucune URL de confiance
// à notifier — inutile (et risqué) de tenter un callback vers une valeur non
// vérifiée. On s'arrête ici : l'erreur reste visible dans les Executions n8n.
if (!callbackUrl) {
  return [];
}

const callbackBody = {
  n8nExecutionId: $execution.id,
  n8nWorkflowId: $workflow.id,
  runId,
  phase: 1,
  resultType: 'account_watch_refresh',
  status: 'failed',
  contentJson: {},
  errorMessage,
};

return [{
  json: {
    runId,
    callbackUrl,
    companyId,
    workspaceId,
    errorMessage,
    rawBody: JSON.stringify(callbackBody),
  }
}];
